using System.Threading;

public sealed class SpscRing<T> {
    private readonly T[] buf;
    private readonly int mask;
    private long head;   // producer-owned (padded onto its own cache line)
    private long tail;   // consumer-owned

    public SpscRing(int capacityPow2) {         // must be a power of two
        if ((capacityPow2 & (capacityPow2 - 1)) != 0) throw new ArgumentException("pow2");
        buf = new T[capacityPow2]; mask = capacityPow2 - 1;
    }

    public bool TryPush(T v) {
        long h = Volatile.Read(ref head);
        long t = Volatile.Read(ref tail);
        if (h - t == buf.Length) return false;         // full
        buf[h & mask] = v;
        Volatile.Write(ref head, h + 1);               // release: item before head
        return true;
    }
    public bool TryPop(out T v) {
        long t = Volatile.Read(ref tail);
        long h = Volatile.Read(ref head);              // acquire: item IS written
        if (h == t) { v = default!; return false; }
        v = buf[t & mask];
        Volatile.Write(ref tail, t + 1);
        return true;
    }
}
// For multiple producers/consumers or blocking, use Channel<T> with a bound.
